#include <array>
#include <chrono>
#include <compare>
#include <format>
#include <iostream>
#include <optional>

namespace bench {

// From bench/time.hpp: a reading of a node's clock, in nanoseconds since that clock's zero.
struct Time {
  std::chrono::nanoseconds since_epoch;
  auto operator<=>(const Time&) const = default;
};

// From bench/supervisor.hpp: whether a stream is fresh, its last entry at most max_age old.
class Freshness {
 public:
  explicit Freshness(std::chrono::nanoseconds max_age) : max_age_(max_age) {}

  void on_message(Time now) { last_ = now; }

  [[nodiscard]] bool fresh(Time now) const {
    return last_ && *last_ <= now && now.since_epoch - last_->since_epoch <= max_age_;
  }

 private:
  std::chrono::nanoseconds max_age_;
  std::optional<Time> last_;
};

}  // namespace bench

// One transform as a watcher sees it: the time it was true, and the time it arrived.
struct Delivery {
  std::chrono::milliseconds stamp;
  std::chrono::milliseconds arrived;
};

int main() {
  using namespace std::chrono_literals;
  const auto at = [](std::chrono::nanoseconds t) { return bench::Time{t}; };

  // The bridge delivers each transform 20 ms after the pose was measured. From 300 ms the
  // simulator's odometry stops advancing, and the same transform arrives again and again.
  constexpr std::array<Delivery, 7> run{{{.stamp = 200ms, .arrived = 220ms},
                                         {.stamp = 250ms, .arrived = 270ms},
                                         {.stamp = 300ms, .arrived = 320ms},
                                         {.stamp = 300ms, .arrived = 420ms},
                                         {.stamp = 300ms, .arrived = 520ms},
                                         {.stamp = 300ms, .arrived = 570ms},
                                         {.stamp = 300ms, .arrived = 620ms}}};
  bench::Freshness by_stamp(250ms);
  bench::Freshness by_arrival(250ms);
  for (const Delivery& delivery : run) {
    by_stamp.on_message(at(delivery.stamp));
    by_arrival.on_message(at(delivery.arrived));
    std::cout << std::format("stamp {:3} ms, arrived {:3} ms: fresh by stamp {:5}, by arrival {}\n",
                             delivery.stamp.count(), delivery.arrived.count(), by_stamp.fresh(at(delivery.arrived)),
                             by_arrival.fresh(at(delivery.arrived)));
  }
}

#include <chrono>
#include <compare>
#include <cstdint>
#include <memory>
#include <optional>
#include <string>

#include <geometry_msgs/msg/transform_stamped.hpp>
#include <rclcpp/rclcpp.hpp>
#include <tf2/exceptions.hpp>
#include <tf2_ros/buffer.hpp>
#include <tf2_ros/transform_listener.hpp>

namespace bench {

// In the bench these come from bench_core: bench/time.hpp and bench/supervisor.hpp.
struct Time {
  std::chrono::nanoseconds since_epoch;
  auto operator<=>(const Time&) const = default;
};

class Freshness {
 public:
  explicit Freshness(std::chrono::nanoseconds max_age) : max_age_(max_age) {}

  void on_message(Time now) { last_ = now; }

  [[nodiscard]] bool fresh(Time now) const {
    return last_ && *last_ <= now && now.since_epoch - last_->since_epoch <= max_age_;
  }

 private:
  std::chrono::nanoseconds max_age_;
  std::optional<Time> last_;
};

}  // namespace bench

namespace bench_nodes {

// Looks up one edge of the frame tree ten times a second and logs each change between fresh and
// stale. The age is measured from the transform's own stamp, the time tf2 would interpolate at.
class FrameWatch : public rclcpp::Node {
 public:
  explicit FrameWatch(const rclcpp::NodeOptions& options = rclcpp::NodeOptions())
      : Node("frame_watch", options),
        parent_(declare_parameter<std::string>("parent_frame", "odom")),
        child_(declare_parameter<std::string>("child_frame", "base_link")),
        transform_(std::chrono::milliseconds(declare_parameter<std::int64_t>("max_age_ms", 250))) {
    timer_ = create_timer(std::chrono::milliseconds(100), [this] { on_tick(); });
  }

 private:
  void on_tick() {
    const bench::Time now_time{std::chrono::nanoseconds(now().nanoseconds())};
    try {
      const geometry_msgs::msg::TransformStamped latest =
          buffer_.lookupTransform(parent_, child_, tf2::TimePointZero);
      const rclcpp::Time stamp(latest.header.stamp);
      transform_.on_message({std::chrono::nanoseconds(stamp.nanoseconds())});
      RCLCPP_INFO_THROTTLE(get_logger(), *get_clock(), 1000, "%s -> %s is %.3f s old", parent_.c_str(),
                           child_.c_str(), (now() - stamp).seconds());
    } catch (const tf2::TransformException& e) {
      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 1000, "no %s -> %s: %s", parent_.c_str(), child_.c_str(),
                           e.what());
    }
    report(transform_.fresh(now_time));
  }

  void report(bool fresh) {
    if (reported_ == fresh) return;
    reported_ = fresh;
    if (fresh) {
      RCLCPP_INFO(get_logger(), "%s -> %s is fresh", parent_.c_str(), child_.c_str());
    } else {
      RCLCPP_WARN(get_logger(), "%s -> %s is stale", parent_.c_str(), child_.c_str());
    }
  }

  std::string parent_;
  std::string child_;
  bench::Freshness transform_;
  std::optional<bool> reported_;  // empty until the first tick, so the first answer is logged
  tf2_ros::Buffer buffer_{get_clock()};
  tf2_ros::TransformListener listener_{buffer_};
  rclcpp::TimerBase::SharedPtr timer_;
};

}  // namespace bench_nodes

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<bench_nodes::FrameWatch>());
  rclcpp::shutdown();
}
